// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_SR: NistCatalogFamily = {"code":"SR","name":"Supply Chain Risk Management","controls":[{"id":"SR-1","oscal_id":"sr-1","family":"SR","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> supply chain risk management policy that:\n    <organization-defined parameter> supply chain risk management policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the supply chain risk management policy and the associated supply chain risk management controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures; and\nc. Review and update the current supply chain risk management:\n  Review and update the current supply chain risk management:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Supply chain risk management policy and procedures address the controls in the SR family as well as supply chain-related controls in other families that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of supply chain risk management policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to supply chain risk management policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"sr-1_prm_1","label":"organization-defined personnel or roles"},{"id":"sr-01_odp.01","label":"personnel or roles"},{"id":"sr-01_odp.02","label":"personnel or roles"},{"id":"sr-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"sr-01_odp.04","label":"official"},{"id":"sr-01_odp.05","label":"frequency"},{"id":"sr-01_odp.06","label":"events"},{"id":"sr-01_odp.07","label":"frequency"},{"id":"sr-01_odp.08","label":"events"}],"objectives":[{"id":"sr-1_obj.a-1","label":"SR-01a.[01]","text":"a supply chain risk management policy is developed and documented;"},{"id":"sr-1_obj.a-2","label":"SR-01a.[02]","text":"the supply chain risk management policy is disseminated to {{ insert: param, sr-01_odp.01 }};"},{"id":"sr-1_obj.a-3","label":"SR-01a.[03]","text":"supply chain risk management procedures to facilitate the implementation of the supply chain risk management policy and the associated supply chain risk management controls are developed and documented;"},{"id":"sr-1_obj.a-4","label":"SR-01a.[04]","text":"the supply chain risk management procedures are disseminated to {{ insert: param, sr-01_odp.02 }}."},{"id":"sr-1_obj.a.1.a-1","label":"SR-01a.01(a)[01]","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses purpose;"},{"id":"sr-1_obj.a.1.a-2","label":"SR-01a.01(a)[02]","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses scope;"},{"id":"sr-1_obj.a.1.a-3","label":"SR-01a.01(a)[03]","text":"{{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses roles;"},{"id":"sr-1_obj.a.1.a-4","label":"SR-01a.01(a)[04]","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses responsibilities;"},{"id":"sr-1_obj.a.1.a-5","label":"SR-01a.01(a)[05]","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses management commitment;"},{"id":"sr-1_obj.a.1.a-6","label":"SR-01a.01(a)[06]","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses coordination among organizational entities;"},{"id":"sr-1_obj.a.1.a-7","label":"SR-01a.01(a)[07]","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy addresses compliance."},{"id":"sr-1_obj.a.1.b","label":"SR-01a.01(b)","text":"the {{ insert: param, sr-01_odp.03 }} supply chain risk management policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"sr-1_obj.b","label":"SR-01b.","text":"the {{ insert: param, sr-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures;"},{"id":"sr-1_obj.c.1-1","label":"SR-01c.01[01]","text":"the current supply chain risk management policy is reviewed and updated {{ insert: param, sr-01_odp.05 }};"},{"id":"sr-1_obj.c.1-2","label":"SR-01c.01[02]","text":"the current supply chain risk management policy is reviewed and updated following {{ insert: param, sr-01_odp.06 }};"},{"id":"sr-1_obj.c.2-1","label":"SR-01c.02[01]","text":"the current supply chain risk management procedures are reviewed and updated {{ insert: param, sr-01_odp.07 }};"},{"id":"sr-1_obj.c.2-2","label":"SR-01c.02[02]","text":"the current supply chain risk management procedures are reviewed and updated following {{ insert: param, sr-01_odp.08 }}."}],"methods":[{"method":"examine","label":"SR-01-Examine"},{"method":"interview","label":"SR-01-Interview"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"CNSSD 505"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"},{"title":"SP 800-161"}],"related_controls":["PM-9","PM-30","PS-8","SI-12"]},{"id":"SR-2","oscal_id":"sr-2","family":"SR","title":"Supply Chain Risk Management Plan","statement":"a. Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of the following systems, system components or system services: <systems, system components, or system services>;\nb. Review and update the supply chain risk management plan <frequency> or as required, to address threat, organizational or environmental changes; and\nc. Protect the supply chain risk management plan from unauthorized disclosure and modification.","supplemental_guidance":"The dependence on products, systems, and services from external providers, as well as the nature of the relationships with those providers, present an increasing level of risk to an organization. Threat actions that may increase security or privacy risks include unauthorized production, the insertion or use of counterfeits, tampering, theft, insertion of malicious software and hardware, and poor manufacturing and development practices in the supply chain. Supply chain risks can be endemic or systemic within a system element or component, a system, an organization, a sector, or the Nation. Managing supply chain risk is a complex, multifaceted undertaking that requires a coordinated effort across an organization to build trust relationships and communicate with internal and external stakeholders. Supply chain risk management (SCRM) activities include identifying and assessing risks, determining appropriate risk response actions, developing SCRM plans to document response actions, and monitoring performance against plans. The SCRM plan (at the system-level) is implementation specific, providing policy implementation, requirements, constraints and implications. It can either be stand-alone, or incorporated into system security and privacy plans. The SCRM plan addresses managing, implementation, and monitoring of SCRM controls and the development/sustainment of systems across the SDLC to support mission and business functions.\n\nBecause supply chains can differ significantly across and within organizations, SCRM plans are tailored to the individual program, organizational, and operational contexts. Tailored SCRM plans provide the basis for determining whether a technology, service, system component, or system is fit for purpose, and as such, the controls need to be tailored accordingly. Tailored SCRM plans help organizations focus their resources on the most critical mission and business functions based on mission and business requirements and their risk environment. Supply chain risk management plans include an expression of the supply chain risk tolerance for the organization, acceptable supply chain risk mitigation strategies or controls, a process for consistently evaluating and monitoring supply chain risk, approaches for implementing and communicating the plan, a description of and justification for supply chain risk mitigation measures taken, and associated roles and responsibilities. Finally, supply chain risk management plans address requirements for developing trustworthy, secure, privacy-protective, and resilient system components and systems, including the application of the security design principles implemented as part of life cycle-based systems security engineering processes (see [SA-8](#sa-8)).","implementation_level":"organization","parameters":[{"id":"sr-02_odp.01","label":"systems, system components, or system services"},{"id":"sr-02_odp.02","label":"frequency"}],"objectives":[{"id":"sr-2_obj.a-1","label":"SR-02a.[01]","text":"a plan for managing supply chain risks is developed;"},{"id":"sr-2_obj.a-2","label":"SR-02a.[02]","text":"the supply chain risk management plan addresses risks associated with the research and development of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-3","label":"SR-02a.[03]","text":"the supply chain risk management plan addresses risks associated with the design of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-4","label":"SR-02a.[04]","text":"the supply chain risk management plan addresses risks associated with the manufacturing of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-5","label":"SR-02a.[05]","text":"the supply chain risk management plan addresses risks associated with the acquisition of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-6","label":"SR-02a.[06]","text":"the supply chain risk management plan addresses risks associated with the delivery of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-7","label":"SR-02a.[07]","text":"the supply chain risk management plan addresses risks associated with the integration of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-8","label":"SR-02a.[08]","text":"the supply chain risk management plan addresses risks associated with the operation and maintenance of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.a-9","label":"SR-02a.[09]","text":"the supply chain risk management plan addresses risks associated with the disposal of {{ insert: param, sr-02_odp.01 }};"},{"id":"sr-2_obj.b","label":"SR-02b.","text":"the supply chain risk management plan is reviewed and updated {{ insert: param, sr-02_odp.02 }} or as required to address threat, organizational, or environmental changes;"},{"id":"sr-2_obj.c-1","label":"SR-02c.[01]","text":"the supply chain risk management plan is protected from unauthorized disclosure;"},{"id":"sr-2_obj.c-2","label":"SR-02c.[02]","text":"the supply chain risk management plan is protected from unauthorized modification."}],"methods":[{"method":"examine","label":"SR-02-Examine"},{"method":"interview","label":"SR-02-Interview"},{"method":"test","label":"SR-02-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"CNSSD 505"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-160-1"},{"title":"SP 800-161"},{"title":"SP 800-181"},{"title":"IR 7622"},{"title":"IR 8272"}],"related_controls":["CA-2","CP-4","IR-4","MA-2","MA-6","PE-16","PL-2","PM-9","PM-30","RA-3","RA-7","SA-8","SI-4"],"enhancements":[{"id":"SR-2(1)","oscal_id":"sr-2.1","family":"SR","title":"Establish SCRM Team","statement":"Establish a supply chain risk management team consisting of <personnel, roles and responsibilities> to lead and support the following SCRM activities: <supply chain risk management activities>.","supplemental_guidance":"To implement supply chain risk management plans, organizations establish a coordinated, team-based approach to identify and assess supply chain risks and manage these risks by using programmatic and technical mitigation techniques. The team approach enables organizations to conduct an analysis of their supply chain, communicate with internal and external partners or stakeholders, and gain broad consensus regarding the appropriate resources for SCRM. The SCRM team consists of organizational personnel with diverse roles and responsibilities for leading and supporting SCRM activities, including risk executive, information technology, contracting, information security, privacy, mission or business, legal, supply chain and logistics, acquisition, business continuity, and other relevant functions. Members of the SCRM team are involved in various aspects of the SDLC and, collectively, have an awareness of and provide expertise in acquisition processes, legal practices, vulnerabilities, threats, and attack vectors, as well as an understanding of the technical aspects and dependencies of systems. The SCRM team can be an extension of the security and privacy risk management processes or be included as part of an organizational risk management team.","implementation_level":"organization","parameters":[{"id":"sr-02.01_odp.01","label":"personnel, roles and responsibilities"},{"id":"sr-02.01_odp.02","label":"supply chain risk management activities"}],"methods":[{"method":"examine","label":"SR-02(01)-Examine"},{"method":"interview","label":"SR-02(01)-Interview"}],"is_enhancement":true,"parent_id":"SR-2"}]},{"id":"SR-3","oscal_id":"sr-3","family":"SR","title":"Supply Chain Controls and Processes","statement":"a. Establish a process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of <system or system component> in coordination with <supply chain personnel>;\nb. Employ the following controls to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events: <supply chain controls> ; and\nc. Document the selected and implemented supply chain processes and controls in <organization-defined parameter>.","supplemental_guidance":"Supply chain elements include organizations, entities, or tools employed for the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of systems and system components. Supply chain processes include hardware, software, and firmware development processes; shipping and handling procedures; personnel security and physical security programs; configuration management tools, techniques, and measures to maintain provenance; or other programs, processes, or procedures associated with the development, acquisition, maintenance and disposal of systems and system components. Supply chain elements and processes may be provided by organizations, system integrators, or external providers. Weaknesses or deficiencies in supply chain elements or processes represent potential vulnerabilities that can be exploited by adversaries to cause harm to the organization and affect its ability to carry out its core missions or business functions. Supply chain personnel are individuals with roles and responsibilities in the supply chain.","implementation_level":"organization","parameters":[{"id":"sr-03_odp.01","label":"system or system component"},{"id":"sr-03_odp.02","label":"supply chain personnel"},{"id":"sr-03_odp.03","label":"supply chain controls"},{"id":"sr-03_odp.04","label":"","choices":["security and privacy plans","supply chain risk management plan","{{ insert: param, sr-03_odp.05 }} "],"how_many":"one-or-more"},{"id":"sr-03_odp.05","label":"document"}],"objectives":[{"id":"sr-3_obj.a-1","label":"SR-03a.[01]","text":"a process or processes is/are established to identify and address weaknesses or deficiencies in the supply chain elements and processes of {{ insert: param, sr-03_odp.01 }};"},{"id":"sr-3_obj.a-2","label":"SR-03a.[02]","text":"the process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of {{ insert: param, sr-03_odp.01 }} is/are coordinated with {{ insert: param, sr-03_odp.02 }};"},{"id":"sr-3_obj.b","label":"SR-03b.","text":"{{ insert: param, sr-03_odp.03 }} are employed to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events;"},{"id":"sr-3_obj.c","label":"SR-03c.","text":"the selected and implemented supply chain processes and controls are documented in {{ insert: param, sr-03_odp.04 }}."}],"methods":[{"method":"examine","label":"SR-03-Examine"},{"method":"interview","label":"SR-03-Interview"},{"method":"test","label":"SR-03-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"ISO 20243"},{"title":"SP 800-30"},{"title":"SP 800-161"},{"title":"IR 7622"}],"related_controls":["CA-2","MA-2","MA-6","PE-3","PE-16","PL-8","PM-30","SA-2","SA-3","SA-4","SA-5","SA-8","SA-9","SA-10","SA-15","SC-7","SC-29","SC-30","SC-38","SI-7","SR-6","SR-9","SR-11"],"enhancements":[{"id":"SR-3(1)","oscal_id":"sr-3.1","family":"SR","title":"Diverse Supply Base","statement":"Employ a diverse set of sources for the following system components and services: <organization-defined system components and services>.","supplemental_guidance":"Diversifying the supply of systems, system components, and services can reduce the probability that adversaries will successfully identify and target the supply chain and can reduce the impact of a supply chain event or compromise. Identifying multiple suppliers for replacement components can reduce the probability that the replacement component will become unavailable. Employing a diverse set of developers or logistics service providers can reduce the impact of a natural disaster or other supply chain event. Organizations consider designing the system to include diverse materials and components.","implementation_level":"organization","parameters":[{"id":"sr-3.1_prm_1","label":"organization-defined system components and services"},{"id":"sr-03.01_odp.01","label":"system components"},{"id":"sr-03.01_odp.02","label":"services"}],"objectives":[{"id":"sr-3.1_obj-1","label":"SR-03(01)[01]","text":"a diverse set of sources is employed for {{ insert: param, sr-03.01_odp.01 }};"},{"id":"sr-3.1_obj-2","label":"SR-03(01)[02]","text":"a diverse set of sources is employed for {{ insert: param, sr-03.01_odp.02 }}."}],"methods":[{"method":"examine","label":"SR-03(01)-Examine"},{"method":"interview","label":"SR-03(01)-Interview"},{"method":"test","label":"SR-03(01)-Test"}],"is_enhancement":true,"parent_id":"SR-3"},{"id":"SR-3(2)","oscal_id":"sr-3.2","family":"SR","title":"Limitation of Harm","statement":"Employ the following controls to limit harm from potential adversaries identifying and targeting the organizational supply chain: <controls>.","supplemental_guidance":"Controls that can be implemented to reduce the probability of adversaries successfully identifying and targeting the supply chain include avoiding the purchase of custom or non-standardized configurations, employing approved vendor lists with standing reputations in industry, following pre-agreed maintenance schedules and update and patch delivery mechanisms, maintaining a contingency plan in case of a supply chain event, using procurement carve-outs that provide exclusions to commitments or obligations, using diverse delivery routes, and minimizing the time between purchase decisions and delivery.","implementation_level":"organization","parameters":[{"id":"sr-03.02_odp","label":"controls"}],"methods":[{"method":"examine","label":"SR-03(02)-Examine"},{"method":"interview","label":"SR-03(02)-Interview"},{"method":"test","label":"SR-03(02)-Test"}],"is_enhancement":true,"parent_id":"SR-3"},{"id":"SR-3(3)","oscal_id":"sr-3.3","family":"SR","title":"Sub-tier Flow Down","statement":"Ensure that the controls included in the contracts of prime contractors are also included in the contracts of subcontractors.","supplemental_guidance":"To manage supply chain risk effectively and holistically, it is important that organizations ensure that supply chain risk management controls are included at all tiers in the supply chain. This includes ensuring that Tier 1 (prime) contractors have implemented processes to facilitate the \"flow down\" of supply chain risk management controls to sub-tier contractors. The controls subject to flow down are identified in [SR-3b](#sr-3_smt.b).","implementation_level":"organization","methods":[{"method":"examine","label":"SR-03(03)-Examine"},{"method":"interview","label":"SR-03(03)-Interview"},{"method":"test","label":"SR-03(03)-Test"}],"related_controls":["SR-5","SR-8"],"is_enhancement":true,"parent_id":"SR-3"}]},{"id":"SR-4","oscal_id":"sr-4","family":"SR","title":"Provenance","statement":"Document, monitor, and maintain valid provenance of the following systems, system components, and associated data: <systems, system components, and associated data>.","supplemental_guidance":"Every system and system component has a point of origin and may be changed throughout its existence. Provenance is the chronology of the origin, development, ownership, location, and changes to a system or system component and associated data. It may also include personnel and processes used to interact with or make modifications to the system, component, or associated data. Organizations consider developing procedures (see [SR-1](#sr-1) ) for allocating responsibilities for the creation, maintenance, and monitoring of provenance for systems and system components; transferring provenance documentation and responsibility between organizations; and preventing and monitoring for unauthorized changes to the provenance records. Organizations have methods to document, monitor, and maintain valid provenance baselines for systems, system components, and related data. These actions help track, assess, and document any changes to the provenance, including changes in supply chain elements or configuration, and help ensure non-repudiation of provenance information and the provenance change records. Provenance considerations are addressed throughout the system development life cycle and incorporated into contracts and other arrangements, as appropriate.","implementation_level":"organization","parameters":[{"id":"sr-04_odp","label":"systems, system components, and associated data"}],"objectives":[{"id":"sr-4_obj-1","label":"SR-04[01]","text":"valid provenance is documented for {{ insert: param, sr-04_odp }};"},{"id":"sr-4_obj-2","label":"SR-04[02]","text":"valid provenance is monitored for {{ insert: param, sr-04_odp }};"},{"id":"sr-4_obj-3","label":"SR-04[03]","text":"valid provenance is maintained for {{ insert: param, sr-04_odp }}."}],"methods":[{"method":"examine","label":"SR-04-Examine"},{"method":"interview","label":"SR-04-Interview"},{"method":"test","label":"SR-04-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"ISO 27036"},{"title":"ISO 20243"},{"title":"SP 800-160-1"},{"title":"SP 800-161"},{"title":"IR 7622"},{"title":"IR 8112"},{"title":"IR 8272"}],"related_controls":["CM-8","MA-2","MA-6","RA-9","SA-3","SA-8","SI-4"],"enhancements":[{"id":"SR-4(1)","oscal_id":"sr-4.1","family":"SR","title":"Identity","statement":"Establish and maintain unique identification of the following supply chain elements, processes, and personnel associated with the identified system and critical system components: <supply chain elements, processes, and personnel>.","supplemental_guidance":"Knowing who and what is in the supply chains of organizations is critical to gaining visibility into supply chain activities. Visibility into supply chain activities is also important for monitoring and identifying high-risk events and activities. Without reasonable visibility into supply chains elements, processes, and personnel, it is very difficult for organizations to understand and manage risk and reduce their susceptibility to adverse events. Supply chain elements include organizations, entities, or tools used for the research and development, design, manufacturing, acquisition, delivery, integration, operations, maintenance, and disposal of systems and system components. Supply chain processes include development processes for hardware, software, and firmware; shipping and handling procedures; configuration management tools, techniques, and measures to maintain provenance; personnel and physical security programs; or other programs, processes, or procedures associated with the production and distribution of supply chain elements. Supply chain personnel are individuals with specific roles and responsibilities related to the secure the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of a system or system component. Identification methods are sufficient to support an investigation in case of a supply chain change (e.g. if a supply company is purchased), compromise, or event.","implementation_level":"organization","parameters":[{"id":"sr-04.01_odp","label":"supply chain elements, processes, and personnel"}],"objectives":[{"id":"sr-4.1_obj-1","label":"SR-04(01)[01]","text":"unique identification of {{ insert: param, sr-04.01_odp }} is established;"},{"id":"sr-4.1_obj-2","label":"SR-04(01)[02]","text":"unique identification of {{ insert: param, sr-04.01_odp }} is maintained."}],"methods":[{"method":"examine","label":"SR-04(01)-Examine"},{"method":"interview","label":"SR-04(01)-Interview"},{"method":"test","label":"SR-04(01)-Test"}],"related_controls":["IA-2","IA-8","PE-16"],"is_enhancement":true,"parent_id":"SR-4"},{"id":"SR-4(2)","oscal_id":"sr-4.2","family":"SR","title":"Track and Trace","statement":"Establish and maintain unique identification of the following systems and critical system components for tracking through the supply chain: <systems and critical system components>.","supplemental_guidance":"Tracking the unique identification of systems and system components during development and transport activities provides a foundational identity structure for the establishment and maintenance of provenance. For example, system components may be labeled using serial numbers or tagged using radio-frequency identification tags. Labels and tags can help provide better visibility into the provenance of a system or system component. A system or system component may have more than one unique identifier. Identification methods are sufficient to support a forensic investigation after a supply chain compromise or event.","implementation_level":"organization","parameters":[{"id":"sr-04.02_odp","label":"systems and critical system components"}],"objectives":[{"id":"sr-4.2_obj-1","label":"SR-04(02)[01]","text":"the unique identification of {{ insert: param, sr-04.02_odp }} is established for tracking through the supply chain;"},{"id":"sr-4.2_obj-2","label":"SR-04(02)[02]","text":"the unique identification of {{ insert: param, sr-04.02_odp }} is maintained for tracking through the supply chain."}],"methods":[{"method":"examine","label":"SR-04(02)-Examine"},{"method":"interview","label":"SR-04(02)-Interview"},{"method":"test","label":"SR-04(02)-Test"}],"related_controls":["IA-2","IA-8","PE-16","PL-2"],"is_enhancement":true,"parent_id":"SR-4"},{"id":"SR-4(3)","oscal_id":"sr-4.3","family":"SR","title":"Validate as Genuine and Not Altered","statement":"Employ the following controls to validate that the system or system component received is genuine and has not been altered: <organization-defined controls>.","supplemental_guidance":"For many systems and system components, especially hardware, there are technical means to determine if the items are genuine or have been altered, including optical and nanotechnology tagging, physically unclonable functions, side-channel analysis, cryptographic hash verifications or digital signatures, and visible anti-tamper labels or stickers. Controls can also include monitoring for out of specification performance, which can be an indicator of tampering or counterfeits. Organizations may leverage supplier and contractor processes for validating that a system or component is genuine and has not been altered and for replacing a suspect system or component. Some indications of tampering may be visible and addressable before accepting delivery, such as inconsistent packaging, broken seals, and incorrect labels. When a system or system component is suspected of being altered or counterfeit, the supplier, contractor, or original equipment manufacturer may be able to replace the item or provide a forensic capability to determine the origin of the counterfeit or altered item. Organizations can provide training to personnel on how to identify suspicious system or component deliveries.","implementation_level":"organization","parameters":[{"id":"sr-4.3_prm_1","label":"organization-defined controls"},{"id":"sr-04.03_odp.01","label":"controls"},{"id":"sr-04.03_odp.02","label":"controls"}],"objectives":[{"id":"sr-4.3_obj-1","label":"SR-04(03)[01]","text":"{{ insert: param, sr-04.03_odp.01 }} are employed to validate that the system or system component received is genuine;"},{"id":"sr-4.3_obj-2","label":"SR-04(03)[02]","text":"{{ insert: param, sr-04.03_odp.02 }} are employed to validate that the system or system component received has not been altered."}],"methods":[{"method":"examine","label":"SR-04(03)-Examine"},{"method":"interview","label":"SR-04(03)-Interview"},{"method":"test","label":"SR-04(03)-Test"}],"related_controls":["AT-3","SR-9","SR-10","SR-11"],"is_enhancement":true,"parent_id":"SR-4"},{"id":"SR-4(4)","oscal_id":"sr-4.4","family":"SR","title":"Supply Chain Integrity — Pedigree","statement":"Employ <controls> and conduct <analysis method> to ensure the integrity of the system and system components by validating the internal composition and provenance of critical or mission-essential technologies, products, and services.","supplemental_guidance":"Authoritative information regarding the internal composition of system components and the provenance of technology, products, and services provides a strong basis for trust. The validation of the internal composition and provenance of technologies, products, and services is referred to as the pedigree. For microelectronics, this includes material composition of components. For software this includes the composition of open-source and proprietary code, including the version of the component at a given point in time. Pedigrees increase the assurance that the claims suppliers assert about the internal composition and provenance of the products, services, and technologies they provide are valid. The validation of the internal composition and provenance can be achieved by various evidentiary artifacts or records that manufacturers and suppliers produce during the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of technology, products, and services. Evidentiary artifacts include, but are not limited to, software identification (SWID) tags, software component inventory, the manufacturers’ declarations of platform attributes (e.g., serial numbers, hardware component inventory), and measurements (e.g., firmware hashes) that are tightly bound to the hardware itself.","implementation_level":"organization","parameters":[{"id":"sr-04.04_odp.01","label":"controls"},{"id":"sr-04.04_odp.02","label":"analysis method"}],"objectives":[{"id":"sr-4.4_obj-1","label":"SR-04(04)[01]","text":"{{ insert: param, sr-04.04_odp.01 }} are employed to ensure the integrity of the system and system components;"},{"id":"sr-4.4_obj-2","label":"SR-04(04)[02]","text":"{{ insert: param, sr-04.04_odp.02 }} is conducted to ensure the integrity of the system and system components."}],"methods":[{"method":"examine","label":"SR-04(04)-Examine"},{"method":"interview","label":"SR-04(04)-Interview"},{"method":"test","label":"SR-04(04)-Test"}],"related_controls":["RA-3"],"is_enhancement":true,"parent_id":"SR-4"}]},{"id":"SR-5","oscal_id":"sr-5","family":"SR","title":"Acquisition Strategies, Tools, and Methods","statement":"Employ the following acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks: <strategies, tools, and methods>.","supplemental_guidance":"The use of the acquisition process provides an important vehicle to protect the supply chain. There are many useful tools and techniques available, including obscuring the end use of a system or system component, using blind or filtered buys, requiring tamper-evident packaging, or using trusted or controlled distribution. The results from a supply chain risk assessment can guide and inform the strategies, tools, and methods that are most applicable to the situation. Tools and techniques may provide protections against unauthorized production, theft, tampering, insertion of counterfeits, insertion of malicious software or backdoors, and poor development practices throughout the system development life cycle. Organizations also consider providing incentives for suppliers who implement controls, promote transparency into their processes and security and privacy practices, provide contract language that addresses the prohibition of tainted or counterfeit components, and restrict purchases from untrustworthy suppliers. Organizations consider providing training, education, and awareness programs for personnel regarding supply chain risk, available mitigation strategies, and when the programs should be employed. Methods for reviewing and protecting development plans, documentation, and evidence are commensurate with the security and privacy requirements of the organization. Contracts may specify documentation protection requirements.","implementation_level":"organization","parameters":[{"id":"sr-05_odp","label":"strategies, tools, and methods"}],"objectives":[{"id":"sr-5_obj-1","label":"SR-05[01]","text":"{{ insert: param, sr-05_odp }} are employed to protect against supply chain risks;"},{"id":"sr-5_obj-2","label":"SR-05[02]","text":"{{ insert: param, sr-05_odp }} are employed to identify supply chain risks;"},{"id":"sr-5_obj-3","label":"SR-05[03]","text":"{{ insert: param, sr-05_odp }} are employed to mitigate supply chain risks."}],"methods":[{"method":"examine","label":"SR-05-Examine"},{"method":"interview","label":"SR-05-Interview"},{"method":"test","label":"SR-05-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"ISO 27036"},{"title":"ISO 20243"},{"title":"SP 800-30"},{"title":"SP 800-161"},{"title":"IR 7622"},{"title":"IR 8272"}],"related_controls":["AT-3","SA-2","SA-3","SA-4","SA-5","SA-8","SA-9","SA-10","SA-15","SR-6","SR-9","SR-10","SR-11"],"enhancements":[{"id":"SR-5(1)","oscal_id":"sr-5.1","family":"SR","title":"Adequate Supply","statement":"Employ the following controls to ensure an adequate supply of <critical system components>: <controls>.","supplemental_guidance":"Adversaries can attempt to impede organizational operations by disrupting the supply of critical system components or corrupting supplier operations. Organizations may track systems and component mean time to failure to mitigate the loss of temporary or permanent system function. Controls to ensure that adequate supplies of critical system components include the use of multiple suppliers throughout the supply chain for the identified critical components, stockpiling spare components to ensure operation during mission-critical times, and the identification of functionally identical or similar components that may be used, if necessary.","implementation_level":"organization","parameters":[{"id":"sr-05.01_odp.01","label":"controls"},{"id":"sr-05.01_odp.02","label":"critical system components"}],"methods":[{"method":"examine","label":"SR-05(01)-Examine"},{"method":"interview","label":"SR-05(01)-Interview"},{"method":"test","label":"SR-05(01)-Test"}],"related_controls":["RA-9"],"is_enhancement":true,"parent_id":"SR-5"},{"id":"SR-5(2)","oscal_id":"sr-5.2","family":"SR","title":"Assessments Prior to Selection, Acceptance, Modification, or Update","statement":"Assess the system, system component, or system service prior to selection, acceptance, modification, or update.","supplemental_guidance":"Organizational personnel or independent, external entities conduct assessments of systems, components, products, tools, and services to uncover evidence of tampering, unintentional and intentional vulnerabilities, or evidence of non-compliance with supply chain controls. These include malicious code, malicious processes, defective software, backdoors, and counterfeits. Assessments can include evaluations; design proposal reviews; visual or physical inspection; static and dynamic analyses; visual, x-ray, or magnetic particle inspections; simulations; white, gray, or black box testing; fuzz testing; stress testing; and penetration testing (see [SR-6(1)](#sr-6.1) ). Evidence generated during assessments is documented for follow-on actions by organizations. The evidence generated during the organizational or independent assessments of supply chain elements may be used to improve supply chain processes and inform the supply chain risk management process. The evidence can be leveraged in follow-on assessments. Evidence and other documentation may be shared in accordance with organizational agreements.","implementation_level":"organization","objectives":[{"id":"sr-5.2_obj-1","label":"SR-05(02)[01]","text":"the system, system component, or system service is assessed prior to selection;"},{"id":"sr-5.2_obj-2","label":"SR-05(02)[02]","text":"the system, system component, or system service is assessed prior to acceptance;"},{"id":"sr-5.2_obj-3","label":"SR-05(02)[03]","text":"the system, system component, or system service is assessed prior to modification;"},{"id":"sr-5.2_obj-4","label":"SR-05(02)[04]","text":"the system, system component, or system service is assessed prior to update."}],"methods":[{"method":"examine","label":"SR-05(02)-Examine"},{"method":"interview","label":"SR-05(02)-Interview"},{"method":"test","label":"SR-05(02)-Test"}],"related_controls":["CA-8","RA-5","SA-11","SI-7"],"is_enhancement":true,"parent_id":"SR-5"}]},{"id":"SR-6","oscal_id":"sr-6","family":"SR","title":"Supplier Assessments and Reviews","statement":"Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide <frequency>.","supplemental_guidance":"An assessment and review of supplier risk includes security and supply chain risk management processes, foreign ownership, control or influence (FOCI), and the ability of the supplier to effectively assess subordinate second-tier and third-tier suppliers and contractors. The reviews may be conducted by the organization or by an independent third party. The reviews consider documented processes, documented controls, all-source intelligence, and publicly available information related to the supplier or contractor. Organizations can use open-source information to monitor for indications of stolen information, poor development and quality control practices, information spillage, or counterfeits. In some cases, it may be appropriate or required to share assessment and review results with other organizations in accordance with any applicable rules, policies, or inter-organizational agreements or contracts.","implementation_level":"organization","parameters":[{"id":"sr-06_odp","label":"frequency"}],"methods":[{"method":"examine","label":"SR-06-Examine"},{"method":"interview","label":"SR-06-Interview"},{"method":"test","label":"SR-06-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"ISO 27036"},{"title":"ISO 20243"},{"title":"FIPS 140-3"},{"title":"FIPS 180-4"},{"title":"FIPS 186-4"},{"title":"FIPS 202"},{"title":"SP 800-30"},{"title":"SP 800-161"},{"title":"IR 7622"},{"title":"IR 8272"}],"related_controls":["SR-3","SR-5"],"enhancements":[{"id":"SR-6(1)","oscal_id":"sr-6.1","family":"SR","title":"Testing and Analysis","statement":"Employ <organization-defined parameter> of the following supply chain elements, processes, and actors associated with the system, system component, or system service: <supply chain elements, processes, and actors>.","supplemental_guidance":"Relationships between entities and procedures within the supply chain, including development and delivery, are considered. Supply chain elements include organizations, entities, or tools that are used for the research and development, design, manufacturing, acquisition, delivery, integration, operations, maintenance, and disposal of systems, system components, or system services. Supply chain processes include supply chain risk management programs; SCRM strategies and implementation plans; personnel and physical security programs; hardware, software, and firmware development processes; configuration management tools, techniques, and measures to maintain provenance; shipping and handling procedures; and programs, processes, or procedures associated with the production and distribution of supply chain elements. Supply chain actors are individuals with specific roles and responsibilities in the supply chain. The evidence generated and collected during analyses and testing of supply chain elements, processes, and actors is documented and used to inform organizational risk management activities and decisions.","implementation_level":"organization","parameters":[{"id":"sr-06.01_odp.01","label":"","choices":["organizational analysis","independent third-party analysis","organizational testing","independent third-party testing"],"how_many":"one-or-more"},{"id":"sr-06.01_odp.02","label":"supply chain elements, processes, and actors"}],"methods":[{"method":"examine","label":"SR-06(01)-Examine"},{"method":"interview","label":"SR-06(01)-Interview"},{"method":"test","label":"SR-06(01)-Test"}],"related_controls":["CA-8","SI-4"],"is_enhancement":true,"parent_id":"SR-6"}]},{"id":"SR-7","oscal_id":"sr-7","family":"SR","title":"Supply Chain Operations Security","statement":"Employ the following Operations Security (OPSEC) controls to protect supply chain-related information for the system, system component, or system service: <OPSEC controls>.","supplemental_guidance":"Supply chain OPSEC expands the scope of OPSEC to include suppliers and potential suppliers. OPSEC is a process that includes identifying critical information, analyzing friendly actions related to operations and other activities to identify actions that can be observed by potential adversaries, determining indicators that potential adversaries might obtain that could be interpreted or pieced together to derive information in sufficient time to cause harm to organizations, implementing safeguards or countermeasures to eliminate or reduce exploitable vulnerabilities and risk to an acceptable level, and considering how aggregated information may expose users or specific uses of the supply chain. Supply chain information includes user identities; uses for systems, system components, and system services; supplier identities; security and privacy requirements; system and component configurations; supplier processes; design specifications; and testing and evaluation results. Supply chain OPSEC may require organizations to withhold mission or business information from suppliers and may include the use of intermediaries to hide the end use or users of systems, system components, or system services.","implementation_level":"organization","parameters":[{"id":"sr-07_odp","label":"OPSEC controls"}],"methods":[{"method":"examine","label":"SR-07-Examine"},{"method":"interview","label":"SR-07-Interview"},{"method":"test","label":"SR-07-Test"}],"references":[{"title":"EO 13873"},{"title":"SP 800-30"},{"title":"ISO 27036"},{"title":"SP 800-161"},{"title":"IR 7622"}],"related_controls":["SC-38"]},{"id":"SR-8","oscal_id":"sr-8","family":"SR","title":"Notification Agreements","statement":"Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the <organization-defined parameter>.","supplemental_guidance":"The establishment of agreements and procedures facilitates communications among supply chain entities. Early notification of compromises and potential compromises in the supply chain that can potentially adversely affect or have adversely affected organizational systems or system components is essential for organizations to effectively respond to such incidents. The results of assessments or audits may include open-source information that contributed to a decision or result and could be used to help the supply chain entity resolve a concern or improve its processes.","implementation_level":"organization","parameters":[{"id":"sr-08_odp.01","label":"","choices":["notification of supply chain compromises","{{ insert: param, sr-08_odp.02 }} "],"how_many":"one-or-more"},{"id":"sr-08_odp.02","label":"results of assessments or audits"}],"methods":[{"method":"examine","label":"SR-08-Examine"},{"method":"interview","label":"SR-08-Interview"},{"method":"test","label":"SR-08-Test"}],"references":[{"title":"FASC18"},{"title":"41 CFR 201"},{"title":"EO 13873"},{"title":"ISO 27036"},{"title":"SP 800-30"},{"title":"SP 800-161"},{"title":"IR 7622"}],"related_controls":["IR-4","IR-6","IR-8"]},{"id":"SR-9","oscal_id":"sr-9","family":"SR","title":"Tamper Resistance and Detection","statement":"Implement a tamper protection program for the system, system component, or system service.","supplemental_guidance":"Anti-tamper technologies, tools, and techniques provide a level of protection for systems, system components, and services against many threats, including reverse engineering, modification, and substitution. Strong identification combined with tamper resistance and/or tamper detection is essential to protecting systems and components during distribution and when in use.","implementation_level":"organization","methods":[{"method":"examine","label":"SR-09-Examine"},{"method":"interview","label":"SR-09-Interview"},{"method":"test","label":"SR-09-Test"}],"references":[{"title":"ISO 20243"}],"related_controls":["PE-3","PM-30","SA-15","SI-4","SI-7","SR-3","SR-4","SR-5","SR-10","SR-11"],"enhancements":[{"id":"SR-9(1)","oscal_id":"sr-9.1","family":"SR","title":"Multiple Stages of System Development Life Cycle","statement":"Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle.","supplemental_guidance":"The system development life cycle includes research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal. Organizations use a combination of hardware and software techniques for tamper resistance and detection. Organizations use obfuscation and self-checking to make reverse engineering and modifications more difficult, time-consuming, and expensive for adversaries. The customization of systems and system components can make substitutions easier to detect and therefore limit damage.","implementation_level":"organization","methods":[{"method":"examine","label":"SR-09(01)-Examine"},{"method":"interview","label":"SR-09(01)-Interview"},{"method":"test","label":"SR-09(01)-Test"}],"related_controls":["SA-3"],"is_enhancement":true,"parent_id":"SR-9"}]},{"id":"SR-10","oscal_id":"sr-10","family":"SR","title":"Inspection of Systems or Components","statement":"Inspect the following systems or system components <organization-defined parameter> to detect tampering: <systems or system components>.","supplemental_guidance":"The inspection of systems or systems components for tamper resistance and detection addresses physical and logical tampering and is applied to systems and system components removed from organization-controlled areas. Indications of a need for inspection include changes in packaging, specifications, factory location, or entity in which the part is purchased, and when individuals return from travel to high-risk locations.","implementation_level":"organization","parameters":[{"id":"sr-10_odp.01","label":"systems or system components"},{"id":"sr-10_odp.02","label":"","choices":["at random","at {{ insert: param, sr-10_odp.03 }} ","upon {{ insert: param, sr-10_odp.04 }} "],"how_many":"one-or-more"},{"id":"sr-10_odp.03","label":"frequency"},{"id":"sr-10_odp.04","label":"indications of need for inspection"}],"methods":[{"method":"examine","label":"SR-10-Examine"},{"method":"interview","label":"SR-10-Interview"},{"method":"test","label":"SR-10-Test"}],"references":[{"title":"ISO 20243"}],"related_controls":["AT-3","PM-30","SI-4","SI-7","SR-3","SR-4","SR-5","SR-9","SR-11"]},{"id":"SR-11","oscal_id":"sr-11","family":"SR","title":"Component Authenticity","statement":"a. Develop and implement anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the system; and\nb. Report counterfeit system components to <organization-defined parameter>.","supplemental_guidance":"Sources of counterfeit components include manufacturers, developers, vendors, and contractors. Anti-counterfeiting policies and procedures support tamper resistance and provide a level of protection against the introduction of malicious code. External reporting organizations include CISA.","implementation_level":"organization","parameters":[{"id":"sr-11_odp.01","label":"","choices":["source of counterfeit component","{{ insert: param, sr-11_odp.02 }} ","{{ insert: param, sr-11_odp.03 }} "],"how_many":"one-or-more"},{"id":"sr-11_odp.02","label":"external reporting organizations"},{"id":"sr-11_odp.03","label":"personnel or roles"}],"objectives":[{"id":"sr-11_obj.a-1","label":"SR-11a.[01]","text":"an anti-counterfeit policy is developed and implemented;"},{"id":"sr-11_obj.a-2","label":"SR-11a.[02]","text":"anti-counterfeit procedures are developed and implemented;"},{"id":"sr-11_obj.a-3","label":"SR-11a.[03]","text":"the anti-counterfeit procedures include the means to detect counterfeit components entering the system;"},{"id":"sr-11_obj.a-4","label":"SR-11a.[04]","text":"the anti-counterfeit procedures include the means to prevent counterfeit components from entering the system;"},{"id":"sr-11_obj.b","label":"SR-11b.","text":"counterfeit system components are reported to {{ insert: param, sr-11_odp.01 }}."}],"methods":[{"method":"examine","label":"SR-11-Examine"},{"method":"interview","label":"SR-11-Interview"},{"method":"test","label":"SR-11-Test"}],"references":[{"title":"ISO 20243"}],"related_controls":["PE-3","SA-4","SI-7","SR-9","SR-10"],"enhancements":[{"id":"SR-11(1)","oscal_id":"sr-11.1","family":"SR","title":"Anti-counterfeit Training","statement":"Train <personnel or roles> to detect counterfeit system components (including hardware, software, and firmware).","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"sr-11.01_odp","label":"personnel or roles"}],"methods":[{"method":"examine","label":"SR-11(01)-Examine"},{"method":"interview","label":"SR-11(01)-Interview"},{"method":"test","label":"SR-11(01)-Test"}],"related_controls":["AT-3"],"is_enhancement":true,"parent_id":"SR-11"},{"id":"SR-11(2)","oscal_id":"sr-11.2","family":"SR","title":"Configuration Control for Component Service and Repair","statement":"Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: <system components>.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"sr-11.02_odp","label":"system components"}],"objectives":[{"id":"sr-11.2_obj-1","label":"SR-11(02)[01]","text":"configuration control over {{ insert: param, sr-11.02_odp }} awaiting service or repair is maintained;"},{"id":"sr-11.2_obj-2","label":"SR-11(02)[02]","text":"configuration control over serviced or repaired {{ insert: param, sr-11.02_odp }} awaiting return to service is maintained."}],"methods":[{"method":"examine","label":"SR-11(02)-Examine"},{"method":"interview","label":"SR-11(02)-Interview"},{"method":"test","label":"SR-11(02)-Test"}],"related_controls":["CM-3","MA-2","MA-4","SA-10"],"is_enhancement":true,"parent_id":"SR-11"},{"id":"SR-11(3)","oscal_id":"sr-11.3","family":"SR","title":"Anti-counterfeit Scanning","statement":"Scan for counterfeit system components <frequency>.","supplemental_guidance":"The type of component determines the type of scanning to be conducted (e.g., web application scanning if the component is a web application).","implementation_level":"organization","parameters":[{"id":"sr-11.03_odp","label":"frequency"}],"methods":[{"method":"examine","label":"SR-11(03)-Examine"},{"method":"interview","label":"SR-11(03)-Interview"},{"method":"test","label":"SR-11(03)-Test"}],"related_controls":["RA-5"],"is_enhancement":true,"parent_id":"SR-11"}]},{"id":"SR-12","oscal_id":"sr-12","family":"SR","title":"Component Disposal","statement":"Dispose of <data, documentation, tools, or system components> using the following techniques and methods: <techniques and methods>.","supplemental_guidance":"Data, documentation, tools, or system components can be disposed of at any time during the system development life cycle (not only in the disposal or retirement phase of the life cycle). For example, disposal can occur during research and development, design, prototyping, or operations/maintenance and include methods such as disk cleaning, removal of cryptographic keys, partial reuse of components. Opportunities for compromise during disposal affect physical and logical data, including system documentation in paper-based or digital files; shipping and delivery documentation; memory sticks with software code; or complete routers or servers that include permanent media, which contain sensitive or proprietary information. Additionally, proper disposal of system components helps to prevent such components from entering the gray market.","implementation_level":"organization","parameters":[{"id":"sr-12_odp.01","label":"data, documentation, tools, or system components"},{"id":"sr-12_odp.02","label":"techniques and methods"}],"methods":[{"method":"examine","label":"SR-12-Examine"},{"method":"interview","label":"SR-12-Interview"},{"method":"test","label":"SR-12-Test"}],"related_controls":["MP-6"]}]};
